-- Made-up test data for /tasks — local dev database only.
--   sqlite3 portfolio.db < scripts/seed-tasks.sql
-- or, without the sqlite3 CLI:
--   python3 -c "import sqlite3; sqlite3.connect('portfolio.db').executescript(open('scripts/seed-tasks.sql').read())"
-- Images are inline SVG data URIs, so no object storage is needed. Re-running
-- replaces the previous seed: it deletes only rows whose image is a data URI,
-- which no real upload ever is.
BEGIN;
DELETE FROM drawing_tasks WHERE image_id IN (SELECT id FROM task_images WHERE image_url LIKE 'data:%');
DELETE FROM task_images WHERE image_url LIKE 'data:%';
COMMIT;
