INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Three spheres on a cloth' AND image_url LIKE 'data:%'), 'Values only', 'Block in the three spheres using three values: light, mid, shadow. No outlines.', 'still life', 'easy', 'value study', 1);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Three spheres on a cloth' AND image_url LIKE 'data:%'), 'Relight from below', 'Redraw the scene with a single light source from below the cloth. Keep the cast shadows consistent.', 'still life', 'hard', 'modification', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Three spheres on a cloth' AND image_url LIKE 'data:%'), 'Ink and hatching', 'Redraw in ink only. Build the form of each sphere with cross-hatching.', 'still life', 'medium', 'style study', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Gesture pose, standing' AND image_url LIKE 'data:%'), 'Thirty-second gestures', 'Five gestures at 30 seconds each. One flowing line for the spine first.', 'figure', 'easy', 'gesture', 1);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Gesture pose, standing' AND image_url LIKE 'data:%'), 'Only the hands', 'Ignore the body and draw the two hands at full page size, guessing what the pose implies.', 'anatomy', 'medium', 'focus study', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Gesture pose, standing' AND image_url LIKE 'data:%'), 'Turn it around', 'Draw the same pose seen from behind. Work out where the weight sits.', 'figure', 'hard', 'modification', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Harbour at dusk' AND image_url LIKE 'data:%'), 'Two-tone silhouette', 'Reduce the harbour to two flat shapes of colour. Keep the boat readable.', 'landscape', 'easy', 'value study', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Harbour at dusk' AND image_url LIKE 'data:%'), 'Watercolour wash', 'Paint the sky in one wet wash, then the water while it is still damp.', 'landscape', 'medium', 'style study', 1);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Harbour at dusk' AND image_url LIKE 'data:%'), 'Morning instead', 'Same harbour, early morning fog. Change only the light and the atmosphere.', 'landscape', 'hard', 'modification', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Old tree by a wall' AND image_url LIKE 'data:%'), 'Bark texture', 'Fill a page with a close study of the bark where the trunk splits.', 'nature', 'medium', 'focus study', 0);
INSERT INTO drawing_tasks (image_id, title, prompt, subject, difficulty, task_type, completed) VALUES ((SELECT id FROM task_images WHERE title = 'Old tree by a wall' AND image_url LIKE 'data:%'), 'Pencil in ten minutes', 'The whole scene in ten minutes, pencil only.', 'nature', 'easy', 'gesture', 0);
